/**
 * Resolve a lesson's `file` (e.g. `limits-intro.mp4`) to a bundled asset.
 *
 * `registry.ts` is generated by `npm run media:sync` and contains the literal
 * `require()` calls Metro needs — nothing here touches the filesystem.
 */

import { docPageAssets, posterAssets, videoAssets } from '../assets/registry';

export type MediaResolution =
  | { kind: 'video'; source: number; poster?: number; durationSec: number }
  | { kind: 'pages'; pages: number[] }
  | { kind: 'missing' };

export function resolveLessonMedia(
  file: string,
  kind: 'video' | 'pdf',
  durationSec: number,
): MediaResolution {
  if (kind === 'video') {
    const source = videoAssets[file];
    if (!source) return { kind: 'missing' };
    return {
      kind: 'video',
      source,
      poster: posterAssets[file.replace(/\.mp4$/, '.jpg')],
      durationSec,
    };
  }
  const pages = docPageAssets[file];
  if (!pages || pages.length === 0) return { kind: 'missing' };
  return { kind: 'pages', pages };
}

/**
 * Resolve just the poster art for a lesson file — used by list thumbnails
 * (Home «أحدث الدروس» and «الدروس» rows) so they show the real video cover
 * instead of the generic course gradient.
 */
export function resolvePoster(file: string): number | undefined {
  return posterAssets[file.replace(/\.(mp4|pdf)$/, '.jpg')];
}

/** Every file bundled with the app — used by the profile screen diagnostics. */
export function bundledAssetCount(): number {
  const videos = Object.keys(videoAssets).length;
  const posters = Object.keys(posterAssets).length;
  const pages = Object.values(docPageAssets).reduce(
    (sum, list) => sum + list.length,
    0,
  );
  return videos + posters + pages;
}
